export function validateExecutionStatusCount(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "status")) fail(contract, `${path}.status`, "missing required property");
  if (!Object.hasOwn(record, "count")) fail(contract, `${path}.count`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "count": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.count`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.count`, "expected integer");
          if ((item as number) < 1.0) fail(contract, `${path}.count`, "must be >= 1.0");
          break;
        }
        case "status": {
          validateReference("GameTapeStatus", validateGameTapeStatus, item, `${path}.status`, contract, refStack);
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateExecutorAdmissionMode(value: unknown, path: string, contract: string): void {
  if (!(["active", "draining"] as unknown[]).includes(value)) fail(contract, path, "was not an allowed enum value");
  if (typeof value !== "string") fail(contract, path, "expected string");
}
